export async function listMembers(
  actor: Actor,
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:read", {
    kind: "organization",
    orgId: input.orgId,
  });
  return memberRepo.listMembers(input);
}

export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);
  const member = await requireActiveMember(input.orgId, input.userId);
  if (input.userId !== actor.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }
  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("Absence end must be after its start");
  }
  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate their absence to themselves");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }
  return memberRepo.upsertAbsence(input);
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  if (userId !== actor.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }
  await memberRepo.deleteAbsence(orgId, userId);
}

export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || absence.endsAt <= new Date().toISOString()) return null;
  return absence;
}

async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/**
 * Role changes carry two rules the permission matrix cannot express:
 * nobody may grant a role above their own, and the last owner may not be
 * demoted. Both are checked after `can()` has had its say.
 */
export async function updateMemberRole(
  actor: Actor,
  input: UpdateMemberRoleInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:update_role", memberResource(member));

  if (!hasRoleAtLeast(actor.role, input.role)) {
    throw new Error(
      `A ${actor.role} cannot grant the ${input.role} role`,
    );
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

