/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const db = getDb();
  const row = db.transaction((tx) => {
    const archived = tx
      .update(members)
      .set({ ...archivePatch(), status: "suspended" })
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning()
      .get();
    if (archived) {
      tx.delete(memberAbsences)
        .where(and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, archived.userId)))
        .run();
      tx.update(memberAbsences)
        .set({ delegateUserId: null })
        .where(and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.delegateUserId, archived.userId)))
        .run();
    }
    return archived;
  });

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

function toMemberAbsence(row: typeof memberAbsences.$inferSelect): MemberAbsence {
  return {
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    delegateUserId: row.delegateUserId === null ? null : brandId<UserId>(row.delegateUserId),
    startsAt: brandStamp(row.startsAt),
    endsAt: brandStamp(row.endsAt),
    note: row.note,
  };
}

export async function findAbsence(orgId: OrgId, userId: UserId): Promise<MemberAbsence | null> {
  const row = getDb().select().from(memberAbsences).where(and(
    orgPredicate(memberAbsences.orgId, orgId),
    eq(memberAbsences.userId, userId),
  )).get();
  return row ? toMemberAbsence(row) : null;
}

export async function findActiveAbsence(orgId: OrgId, userId: UserId, at: IsoTimestamp): Promise<MemberAbsence | null> {
  const row = getDb().select().from(memberAbsences).where(and(
    orgPredicate(memberAbsences.orgId, orgId),
    eq(memberAbsences.userId, userId),
  )).get();
  if (!row || row.startsAt > at || row.endsAt <= at) return null;
  return toMemberAbsence(row);
}

export async function upsertAbsence(input: SetAbsenceInput): Promise<MemberAbsence> {
  const row = getDb().insert(memberAbsences).values(input)
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
      },
    })
    .returning()
    .get();
  return toMemberAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb().delete(memberAbsences).where(and(
    orgPredicate(memberAbsences.orgId, orgId),
    eq(memberAbsences.userId, userId),
  )).run();
}

